e_count(0);expect(page.get_by_text('مرحبا',exact=True)).to_be_visible();assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.close();print(lang,'Next voice/document successfuloutput,autosavewarning,subsequentretryclear,width PASS')
